import os
import re
import shutil
import subprocess
import time
from langchain_core.tools import tool
SOCIALCTL_BINARY = shutil.which('socialctl') or '/opt/social-suite/bin/socialctl'
WORKSPACE_SLUG_PATTERN = re.compile('^[a-z0-9][a-z0-9-]{1,62}$')
PURGE_TIMEOUT_SECONDS = 600
PURGE_REPORT_DIR = '/var/lib/social-suite/purge-reports'
PURGE_REPORT_ARCHIVE_DIR = '/var/lib/social-suite/purge-reports/archive'

def _parse_purge_summary(output_text):
    summary = {'drafts_deleted': 0, 'media_deleted': 0}
    for line in output_text.splitlines():
        drafts_match = re.search('drafts_deleted=(\\d+)', line)
        media_match = re.search('media_deleted=(\\d+)', line)
        if drafts_match:
            summary['drafts_deleted'] = int(drafts_match.group(1))
        if media_match:
            summary['media_deleted'] = int(media_match.group(1))
    return summary

@tool
def purge_stale_post_drafts(workspace_slug: str, older_than_days: int, include_media: bool=False) -> dict:
    if not WORKSPACE_SLUG_PATTERN.match(workspace_slug or ''):
        return {'ok': False, 'error': 'invalid workspace_slug'}
    if older_than_days < 7:
        return {'ok': False, 'error': 'older_than_days must be at least 7'}
    command = [SOCIALCTL_BINARY, 'drafts', 'purge', '--workspace', workspace_slug, '--older-than', f'{older_than_days}d', '--status', 'unscheduled', '--yes']
    if include_media:
        command.append('--with-orphaned-media')
    with subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as process:
        try:
            stdout_text, stderr_text = process.communicate(timeout=PURGE_TIMEOUT_SECONDS)
        except subprocess.TimeoutExpired:
            process.kill()
            process.communicate()
            return {'ok': False, 'error': f'purge timed out after {PURGE_TIMEOUT_SECONDS}s'}
        return_code = process.returncode
    if return_code != 0:
        return {'ok': False, 'exit_code': return_code, 'error': stderr_text.strip()[-1000:]}
    # Move the purge report socialctl wrote into the archive folder under a timestamped name
    report_path = os.path.join(PURGE_REPORT_DIR, f'{workspace_slug}-latest.json')
    if os.path.exists(report_path):
        os.makedirs(PURGE_REPORT_ARCHIVE_DIR, exist_ok=True)
        archived_name = f'{workspace_slug}-{time.strftime("%Y%m%dT%H%M%S")}.json'
        shutil.move(report_path, os.path.join(PURGE_REPORT_ARCHIVE_DIR, archived_name))
    summary = _parse_purge_summary(stdout_text)
    return {'ok': True, 'workspace': workspace_slug, **summary}
